// Two variable definitions
const conc = [0.7, 0.75, 0.8, 0.85, 0.9, 0.95, 1, 1.05, 1.1, 1.15, 1.2, 1.25, 1.3];
const c1 = OLI.random(0,12);1
const c2 = OLI.random(0,12);
const c3 = OLI.random(0,12);
const c4 = OLI.random(0,12);
const acidconc = conc[c1] .toPrecision(3);
const baseconc = conc[c2] .toPrecision(3);
const concoh = conc[c3] .toPrecision(3);
const conchno3 = conc[c4] .toPrecision(3);

const ka = 1e-14/4.4e-4;
const pka = -Math.log10(ka);
const ratio = baseconc/acidconc;
const temp= Math.log10(ratio);
const tempsf = temp .toPrecision(2);
const ph = pka + temp;
const phsf = ph .toPrecision(4);
const phlow = 0.99*ph;
const phhigh = 1.01*ph;

const v1 = [75, 80, 85, 90, 95];
const c5 = OLI.random(0,4);
const volnaoh = v1[c5] .toPrecision(3); 
const c6 = OLI.random(0,4);
const volhno3 = v1[c6] .toPrecision(3);

const molha = acidconc*.250;
const molhasf = molha .toPrecision(3);
const mola = baseconc*.25;
const molasf = mola .toPrecision(3);
const moloh = volnaoh/1000*concoh;
const molohsf = moloh .toPrecision(3);
const molhno3 = volhno3/1000*conchno3;
const molhno3sf = molhno3 .toPrecision(4);

// pH after adding base
const acid = molha-moloh;
const acidsf = acid .toPrecision(3);
const base = mola+moloh;
const basesf = base .toPrecision(3);
const ph2 = pka + Math.log10(base/acid);
const ph2sf = ph2 .toPrecision(4);
const ph2low = 0.99*ph2;
const ph2high = 1.01*ph2;

//pH after adding HNO3
const base2 = mola - molhno3;
const base2sf = base2 .toPrecision(3);
const acid2 = molha + molhno3;
const acid2sf = acid2 .toPrecision(3);
const ph3 = pka + Math.log10(base2/acid2);
const ph3sf = ph3 .toPrecision(4);
const ph3low = 0.99*ph3;
const ph3high = 1.01*ph3;

// Expose variables to OLI
module.exports = {
  acidconc, baseconc, ka, pka, ratio, temp, tempsf, ph, phsf, phlow, phhigh, volnaoh, molhasf, molasf, molohsf, molhno3sf, acidsf, basesf, ph2, ph2sf, concoh, volnaoh, ph2low, ph2high, conchno3, volhno3, base2sf, acid2sf, ph3, ph3sf, ph3low, ph3high
};
